// Para cada combinação ativa (estratégia + versão + símbolo + intervalo), dois
// backtests: os últimos 30 dias e os 90 dias anteriores, para comparar.
const DIA_MS = 24 * 60 * 60 * 1000;
const RECENTE_DIAS = 30;
const BASE_DIAS = 90;

const escaparHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const entrada = $input.all();
const erro = entrada.find((i) => i.json && i.json.error);
if (erro) {
  return [{ json: { semBacktests: true, motivo: escaparHtml(`não consegui listar os robôs (${erro.json.error.message || 'erro'}).`) } }];
}

const fim = Math.floor(Date.now() / DIA_MS) * DIA_MS; // meia-noite UTC: janelas estáveis
const grupos = new Map();
for (const r of entrada.map((i) => i.json)) {
  if (!r || typeof r.id !== 'string' || r.pausado !== false) continue;
  const chave = `${r.estrategiaId}@${r.estrategiaVersao}|${r.simbolo}|${r.intervalo}`;
  const grupo = grupos.get(chave) || {
    chave,
    robos: [],
    base: { estrategiaId: r.estrategiaId, versao: r.estrategiaVersao, simbolo: r.simbolo, intervalo: r.intervalo },
  };
  grupo.robos.push(r.nome || r.id);
  grupos.set(chave, grupo);
}

const janelas = [
  { janela: 'recente', inicio: fim - RECENTE_DIAS * DIA_MS, fim },
  { janela: 'base', inicio: fim - (RECENTE_DIAS + BASE_DIAS) * DIA_MS, fim: fim - RECENTE_DIAS * DIA_MS },
];
const itens = [];
for (const g of grupos.values()) {
  for (const j of janelas) {
    itens.push({
      json: {
        chave: g.chave,
        janela: j.janela,
        robos: g.robos,
        corpoBacktest: { ...g.base, inicio: j.inicio, fim: j.fim },
      },
    });
  }
}

if (itens.length === 0) return [{ json: { semBacktests: true, motivo: 'nenhum robô ativo para revalidar.' } }];
return itens;

// Casa cada backtest planejado com a resposta de POST /api/v1/backtests (mesma ordem).
const planos = $('Planejar backtests').all();
const disparos = $('Disparar backtest').all();

return planos.map((plano, i) => {
  const d = (disparos[i] && disparos[i].json) || {};
  const id = typeof d.id === 'string' && d.id.length > 0 ? d.id : null;
  const erro = d.error ? String(d.error.message || 'erro') : id ? null : 'a API não devolveu o id';
  return { json: { ...plano.json, backtestId: id, erroDisparo: erro } };
});

// Compara, por combinação, os últimos 30 dias com os 90 anteriores (normalizados
// para 30 dias). Lê as métricas com tolerância a nomes, porque o formato do
// resultado do backtest ainda não está fixado em @zentrade/contratos.
const RECENTE_DIAS = 30;
const BASE_DIAS = 90;
const CONCLUIDO = ['concluido', 'concluído', 'pronto', 'finalizado', 'sucesso'];
const NOMES = {
  retorno: ['retornoTotal', 'retorno', 'resultado', 'resultadoLiquido'],
  queda: ['maiorQueda', 'quedaMaxima', 'drawdownMaximo'],
  operacoes: ['operacoes', 'numeroOperacoes', 'totalOperacoes'],
  acerto: ['taxaAcerto', 'acerto'],
};

const escaparHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const planos = $('Ids para consultar').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json || {});

const pegar = (m, nomes) => {
  for (const n of nomes) if (m[n] !== undefined && m[n] !== null) return m[n];
  return undefined;
};
const metricasDe = (r) => (r.metricas && typeof r.metricas === 'object' ? r.metricas : r);
const numero = (v) => (typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN);
const mostrar = (v) => (v === undefined ? '—' : String(v));

const grupos = new Map();
planos.forEach((p, i) => {
  const g = grupos.get(p.chave) || { robos: p.robos, corpo: p.corpoBacktest };
  const r = resultados[i] || {};
  let situacao;
  if (!p.backtestId) situacao = { tipo: 'erro', texto: `não disparou (${p.erroDisparo})` };
  else if (r.error) situacao = { tipo: 'erro', texto: `não consegui consultar (${r.error.message || 'erro'})` };
  else if (!CONCLUIDO.includes(String(r.estado || '').toLowerCase()) && !r.metricas)
    situacao = { tipo: 'pendente', texto: `ainda rodando (estado: ${r.estado || 'desconhecido'}); veja na tela` };
  else situacao = { tipo: 'ok', metricas: metricasDe(r) };
  g[p.janela] = situacao;
  grupos.set(p.chave, g);
});

const linha = (rotulo, s) => {
  if (!s) return `${rotulo}: sem dados`;
  if (s.tipo !== 'ok') return `${rotulo}: ${s.texto}`;
  const m = s.metricas;
  return `${rotulo}: retorno ${mostrar(pegar(m, NOMES.retorno))} · maior queda ${mostrar(pegar(m, NOMES.queda))} · operações ${mostrar(pegar(m, NOMES.operacoes))} · acerto ${mostrar(pegar(m, NOMES.acerto))}`;
};

const blocos = [];
for (const [chave, g] of grupos) {
  const [estrategia, simbolo, intervalo] = chave.split('|');
  const bloco = [
    `${estrategia} · ${simbolo} ${intervalo} (robôs: ${g.robos.join(', ')})`,
    linha(`  Últimos ${RECENTE_DIAS} dias`, g.recente),
    linha(`  ${BASE_DIAS} dias anteriores`, g.base),
  ];
  if (g.recente && g.base && g.recente.tipo === 'ok' && g.base.tipo === 'ok') {
    const recente = numero(pegar(g.recente.metricas, NOMES.retorno));
    const base = numero(pegar(g.base.metricas, NOMES.retorno)) * (RECENTE_DIAS / BASE_DIAS);
    if (Number.isFinite(recente) && Number.isFinite(base)) {
      bloco.push(
        recente < base
          ? '  Atenção: o retorno recente está abaixo do histórico (por 30 dias). Vale revisar a estratégia antes de mantê-la em auto.'
          : '  O retorno recente está em linha com o histórico ou acima dele.',
      );
    }
  }
  blocos.push(bloco.join('\n'));
}

const texto = [
  'ZenTrade — revalidação semanal',
  '',
  ...blocos.flatMap((b) => [b, '']),
  'Backtest mede o passado com as taxas configuradas; não é promessa de resultado futuro.',
].join('\n');

return [{ json: { texto: escaparHtml(texto) } }];
